// El sobre ya lo ha comprobado Pedidos. Aquí falta lo de support.requested: el id del ticket.
// ruta: 0 incompleto, 1 correcto
const ev = $('Desde Pedidos').item.json;
const missing = [];
if (ev.type !== 'support.requested') missing.push('type');
if (!(Number.isInteger(ev.entity_id) && ev.entity_id > 0)) missing.push('entity_id');
return { json: { ...ev, data: ev.data ?? {}, missing, ruta: missing.length ? 0 : 1 } };

// Incidencia de la tienda -> cuerpo de POST /bo-api/tickets (docs/integracion.md, apartado 3)
// El mensaje no se guarda en el back-office: solo se le pasará al agente.
const t = $json;
return { json: {
  event_id: $('Validar').item.json.event_id,
  shop_ticket_id: t.id,
  customer: { name: t.customer.name, email: t.customer.email },
  order_code: t.order_code, // null si el ticket no quedó vinculado al pedido
  reason: t.subject,
  opened_at: t.opened_at,
} };

// Igual que en Pedidos: la red o un 5xx se reintentan (pendiente); un 4xx no se arregla reintentando (error)
const err = $json.error ?? {};
const status = Number(err.httpCode ?? String(err.message ?? '').match(/^(\d{3})/)?.[1] ?? 0);
const map = {
  401: ['error', 'clave_no_valida'],
  404: ['error', 'ticket_no_existe_en_tienda'],
};
const [result, error_type] = map[status] ?? (status >= 400 && status < 500 ? ['error', 'datos_no_validos'] : ['pendiente', 'tienda_no_disponible']);
return { json: { result, error_type, message: 'Pedir incidencia a la tienda: ' + String(err.message ?? 'La tienda no respondió').slice(0, 500) } };

// Error del back-office: 422/401 no se reintentan; la red o un 5xx, sí (pendiente)
const err = $json.error ?? {};
const status = Number(err.httpCode ?? String(err.message ?? '').match(/^(\d{3})/)?.[1] ?? 0);
const map = {
  422: ['error', 'datos_no_validos'],
  401: ['error', 'clave_no_valida'],
};
const [result, error_type] = map[status] ?? ['pendiente', 'backoffice_no_disponible'];
return { json: { result, error_type, message: 'Crear ticket en el back-office: ' + String(err.message ?? 'El back-office no respondió').slice(0, 500) } };
